t.script:
(function() {
    'use strict';

    var barcodeInput = document.getElementById('barcode_scanner');
    var idNumberInput = document.getElementById('id_number_input');
    var notesInput = document.getElementById('notes_input');
    var submitIdBtn = document.getElementById('submit_id_btn');
    var mainStatus = document.getElementById('main_status');
    var assetStatus = document.getElementById('asset_status');
    var communityStatus = document.getElementById('community_status');
    var successMessage = document.getElementById('success_message');
    var errorMessage = document.getElementById('error_message');
    var assetName = document.getElementById('asset_name');
    var borrowerInfo = document.getElementById('borrower_info');
    var communityName = document.getElementById('community_name');
    var requestUuid = document.getElementById('request_uuid');
    var errorText = document.getElementById('error_text');
    var instructions = document.getElementById('instructions');
    var idInputSection = document.getElementById('id_input_section');
    var notesSection = document.getElementById('notes_section');
    var submitSection = document.getElementById('submit_section');
    var borrowBtn = document.getElementById('borrow_btn');
    var borrowWarning = document.getElementById('borrow_warning');
    var requestTypeSection = document.getElementById('request_type_section');
    var assetStatusMessage = document.getElementById('asset_status_message');
    var assetStatusText = document.getElementById('asset_status_text');

    var currentScan = '';
    var scanTimeout = null;
    var assetScanned = false;
    var communityScanned = false;
    var selectedRequestType = null;
    var canBorrow = true;
    var currentAssetStatus = null;

    // Force focus every 500ms (only if asset not scanned and user not typing in notes)
    function forceFocus() {
        var activeElement = document.activeElement;
        // Don't interfere if user is typing in notes or ID input
        if (!assetScanned && activeElement !== barcodeInput && activeElement !== notesInput && activeElement !== idNumberInput) {
            barcodeInput.focus();
        }
    }
    setInterval(forceFocus, 500);

    // Initial focus
    setTimeout(function() {
        barcodeInput.focus();
    }, 100);

    // Handle barcode scanner input
    barcodeInput.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
            e.preventDefault();
            var scanValue = currentScan.trim();
            if (scanValue) {
                processScan(scanValue);
                currentScan = '';
                barcodeInput.value = '';
            }
        } else if (e.key.length === 1) {
            currentScan += e.key;
            // Reset timeout
            if (scanTimeout) {
                clearTimeout(scanTimeout);
            }
            scanTimeout = setTimeout(function() {
                var scanValue = currentScan.trim();
                if (scanValue) {
                    processScan(scanValue);
                    currentScan = '';
                    barcodeInput.value = '';
                }
            }, 100);
        }
    });

    // Process scan using jsonrpc
    function processScan(scanValue) {
        hideAllMessages();
        mainStatus.textContent = 'PROCESSING...';
        mainStatus.style.color = '#d4af37';

        // Simple jsonrpc call
        var jsonrpcData = {
            jsonrpc: '2.0',
            method: 'call',
            params: {scan_value: scanValue},
            id: Math.floor(Math.random() * 1000000)
        };

        fetch('/logilink/kiosk/scan', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(jsonrpcData)
        })
            .then(function(response) {
                return response.json();
            })
            .then(function(data) {
                var result = data.result || data;
                if (result && result.success) {
                    if (result.type === 'asset') {
                        assetScanned = true;
                        assetName.textContent = result.name;
                        currentAssetStatus = result.asset_status;

                        // Check if asset status is 'Working'
                        var isWorking = result.asset_status === 'working';

                        // Display borrower information
                        if (result.borrower_info) {
                            borrowerInfo.textContent = result.borrower_info;
                            borrowerInfo.style.display = 'block';
                            if (result.is_currently_borrowed) {
                                borrowerInfo.style.borderLeftColor = '#dc3545'; // Red for currently borrowed
                                borrowerInfo.style.color = '#dc3545';
                            } else {
                                borrowerInfo.style.borderLeftColor = '#d4af37'; // Gold for last borrower
                                borrowerInfo.style.color = '#666';
                            }
                        } else {
                            borrowerInfo.textContent = 'No borrowing history';
                            borrowerInfo.style.display = 'block';
                            borrowerInfo.style.borderLeftColor = '#28a745'; // Green for available
                            borrowerInfo.style.color = '#28a745';
                        }

                        // Show/hide request type section based on asset status
                        if (isWorking) {
                            // Asset is Working - show request type buttons
                            requestTypeSection.style.display = 'block';
                            assetStatusMessage.style.display = 'none';

                            // Check if asset can be borrowed (not currently borrowed)
                            canBorrow = result.can_borrow !== false;

                            // Enable/disable Borrow button
                            if (!canBorrow) {
                                borrowBtn.disabled = true;
                                borrowBtn.style.background = '#cccccc';
                                borrowBtn.style.color = '#666';
                                borrowBtn.style.borderColor = '#cccccc';
                                borrowBtn.style.cursor = 'not-allowed';
                                borrowBtn.style.opacity = '0.6';
                                borrowWarning.textContent = result.borrow_reason || 'Borrow is not available for this asset.';
                                borrowWarning.style.display = 'block';
                            } else {
                                borrowBtn.disabled = false;
                                borrowBtn.style.background = '#d4af37';
                                borrowBtn.style.color = '#1e3a5f';
                                borrowBtn.style.borderColor = '#d4af37';
                                borrowBtn.style.cursor = 'pointer';
                                borrowBtn.style.opacity = '1';
                                borrowWarning.style.display = 'none';
                            }
                        } else {
                            // Asset is NOT Working - hide all buttons, show message
                            requestTypeSection.style.display = 'none';
                            assetStatusMessage.style.display = 'block';

                            // Get status label
                            var statusLabels = {
                                'broken': 'Broken',
                                'under_maintenance': 'Under Maintenance',
                                'retired': 'Retired',
                                'disposed': 'Disposed',
                                'lost': 'Lost',
                                'reserved': 'Reserved'
                            };
                            var statusLabel = statusLabels[result.asset_status] || result.asset_status;
                            assetStatusText.textContent = 'Current Asset Status: ' + statusLabel;
                        }

                        assetStatus.style.display = 'block';
                        mainStatus.style.display = 'none'; // Hide main status to avoid overlap
                        // Hide instructions
                        instructions.style.display = 'none';
                    } else if (result.type === 'community') {
                        communityScanned = true;
                        communityName.textContent = result.name;
                        communityStatus.style.display = 'block';

                        if (result.request_created) {
                            // Request created successfully
                            hideAllMessages();
                            requestUuid.textContent = 'UUID: ' + result.request_uuid;
                            successMessage.style.display = 'block';
                            mainStatus.textContent = 'REQUEST CREATED';
                            mainStatus.style.color = '#28a745';

                            // Reset after 3 seconds
                            setTimeout(function() {
                                resetKiosk();
                            }, 3000);
                        } else {
                            mainStatus.textContent = 'BORROWER SCANNED';
                            mainStatus.style.color = '#d4af37';
                        }
                    }
                } else {
                    showError(result ? result.message : 'Unknown error');
                }
                // Refocus based on state
                setTimeout(function() {
                    if (assetScanned) {
                        idNumberInput.focus();
                    } else {
                        barcodeInput.focus();
                    }
                }, 100);
            })
            .catch(function(error) {
                showError('Network error: ' + (error.message || error));
                setTimeout(function() {
                    if (assetScanned) {
                        idNumberInput.focus();
                    } else {
                        barcodeInput.focus();
                    }
                }, 100);
            });
    }

    // Handle request type selection
    var requestTypeButtons = document.querySelectorAll('.request_type_btn');
    requestTypeButtons.forEach(function(btn) {
        btn.addEventListener('click', function() {
            // Don't allow selection if button is disabled
            if (this.disabled) {
                return;
            }

            selectedRequestType = this.getAttribute('data-type');

            // Update button styles
            requestTypeButtons.forEach(function(b) {
                if (!b.disabled) {
                    b.style.background = 'white';
                    b.style.color = '#1e3a5f';
                    b.style.borderColor = '#1e3a5f';
                }
            });
            if (!this.disabled) {
                this.style.background = '#d4af37';
                this.style.color = '#1e3a5f';
                this.style.borderColor = '#d4af37';
            }

            // Show/hide sections based on request type
            if (selectedRequestType === 'borrow') {
                if (!canBorrow) {
                    return; // Don't proceed if borrow is not allowed
                }
                idInputSection.style.display = 'block';
                notesSection.style.display = 'block';
                submitSection.style.display = 'block';
                setTimeout(function() {
                    idNumberInput.focus();
                }, 100);
            } else if (selectedRequestType === 'return' || selectedRequestType === 'repair') {
                idInputSection.style.display = 'none';
                notesSection.style.display = 'block';
                submitSection.style.display = 'block';
                setTimeout(function() {
                    notesInput.focus();
                }, 100);
            }

            // Stop forcing focus on barcode input once request type is selected
            assetScanned = true;
        });
    });

    function showRequestTypeButtons() {
        // Request type buttons are already visible in the template
        // Just ensure they're ready
    }

    // Handle manual ID number input
    idNumberInput.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
            e.preventDefault();
            if (notesInput.value.trim() || confirm('No notes entered. Submit anyway?')) {
                submitRequest();
            }
        }
    });

    notesInput.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' && e.ctrlKey) {
            e.preventDefault();
            submitRequest();
        }
    });

    submitIdBtn.addEventListener('click', function() {
        submitRequest();
    });

    function submitRequest() {
        if (!selectedRequestType) {
            showError('Please select a request type');
            return;
        }

        if (!assetScanned) {
            showError('Please scan an asset first');
            return;
        }

        // Check if borrow is allowed
        if (selectedRequestType === 'borrow' && !canBorrow) {
            showError('Borrow is not available for this asset. ' + (borrowWarning.textContent || ''));
            return;
        }

        var idNumber = '';
        var notes = notesInput.value.trim();

        if (selectedRequestType === 'borrow') {
            idNumber = idNumberInput.value.trim();
            if (!idNumber) {
                showError('Please enter an ID Number');
                idNumberInput.focus();
                return;
            }
        }

        // Create request via jsonrpc
        createRequest(selectedRequestType, idNumber, notes);
    }

    function createRequest(requestType, idNumber, notes) {
        hideAllMessages();
        mainStatus.textContent = 'CREATING REQUEST...';
        mainStatus.style.color = '#d4af37';
        mainStatus.style.display = 'block';

        var jsonrpcData = {
            jsonrpc: '2.0',
            method: 'call',
            params: {
                request_type: requestType,
                id_number: idNumber,
                notes: notes
            },
            id: Math.floor(Math.random() * 1000000)
        };

        fetch('/logilink/kiosk/create_request', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(jsonrpcData)
        })
        .then(function(response) {
            return response.json();
        })
        .then(function(data) {
            var result = data.result || data;
            if (result && result.success) {
                // Request created successfully
                hideAllMessages();
                assetStatus.style.display = 'none'; // Hide asset card
                requestUuid.textContent = 'UUID: ' + result.request_uuid;
                successMessage.style.display = 'block';
                mainStatus.textContent = 'REQUEST CREATED';
                mainStatus.style.color = '#28a745';
                mainStatus.style.display = 'block';

                // Reset after 3 seconds
                setTimeout(function() {
                    resetKiosk();
                }, 3000);
            } else {
                showError(result ? result.message : 'Unknown error');
            }
        })
        .catch(function(error) {
            showError('Network error: ' + (error.message || error));
        });
    }

    function showError(message) {
        errorText.textContent = message;
        errorMessage.style.display = 'block';
        mainStatus.textContent = 'ERROR';
        mainStatus.style.color = '#dc3545';
    }

    function hideAllMessages() {
        assetStatus.style.display = 'none';
        communityStatus.style.display = 'none';
        successMessage.style.display = 'none';
        errorMessage.style.display = 'none';
        borrowerInfo.style.display = 'none';
        requestTypeSection.style.display = 'none';
        assetStatusMessage.style.display = 'none';
    }

    function resetKiosk() {
        hideAllMessages();
        assetScanned = false;
        communityScanned = false;
        selectedRequestType = null;
        idNumberInput.value = '';
        notesInput.value = '';

        // Reset request type buttons
        canBorrow = true;
        currentAssetStatus = null;
        requestTypeSection.style.display = 'none';
        assetStatusMessage.style.display = 'none';
        requestTypeButtons.forEach(function(btn) {
            if (btn.getAttribute('data-type') === 'borrow') {
                btn.disabled = false;
                btn.style.background = '#d4af37';
                btn.style.color = '#1e3a5f';
                btn.style.borderColor = '#d4af37';
                btn.style.cursor = 'pointer';
                btn.style.opacity = '1';
            } else {
                btn.style.background = 'white';
                btn.style.color = '#1e3a5f';
                btn.style.borderColor = '#1e3a5f';
            }
        });
        borrowWarning.style.display = 'none';

        idInputSection.style.display = 'none';
        notesSection.style.display = 'none';
        submitSection.style.display = 'none';

        mainStatus.textContent = 'WAITING FOR SCAN';
        mainStatus.style.color = '#1e3a5f';
        mainStatus.style.display = 'block'; // Show main status again
        instructions.style.display = 'block';

        // Clear session via jsonrpc
        fetch('/logilink/kiosk/clear', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {},
                id: Math.floor(Math.random() * 1000000)
            })
        });

        setTimeout(function() {
            barcodeInput.focus();
        }, 100);
    }

    // Keep focus on appropriate input (but don't interfere if user clicks on notes or inputs)
    document.addEventListener('click', function(e) {
        var target = e.target;
        // Don't refocus if user clicked on notes, ID input, or submit button
        if (target === notesInput || target === idNumberInput || target === submitIdBtn || 
            target.closest('#notes_section') || target.closest('#id_input_section') || 
            target.closest('#submit_section')) {
            return;
        }

        setTimeout(function() {
            var activeElement = document.activeElement;
            // Only refocus if user is not actively typing
            if (activeElement !== notesInput && activeElement !== idNumberInput) {
                if (assetScanned && selectedRequestType === 'borrow' && idInputSection.style.display !== 'none') {
                    idNumberInput.focus();
                } else if (assetScanned && (selectedRequestType === 'return' || selectedRequestType === 'repair')) {
                    notesInput.focus();
                } else if (!assetScanned) {
                    barcodeInput.focus();
                }
            }
        }, 100);
    });

    // Prevent context menu
    document.addEventListener('contextmenu', function(e) {
        e.preventDefault();
    });
})();
